DROP DATABASE IF EXISTS customer_behaviour;
CREATE DATABASE customer_behaviour;
SHOW DATABASES;
use customer_behaviour;
show tables;
DESCRIBE customer_data;


-- Q1 what is the total revenue generated by male vs female customer?
select gender, sum(purchase_amount) as revenue
from customer_data
group by gender;

-- Q2 which customer used a discount but still spent more than the average purchase amount?
SELECT customer_id, purchase_amount
FROM customer_data
WHERE discount_applied = 'Yes'
  AND purchase_amount >= (SELECT AVG(purchase_amount) FROM customer_data);
  
-- Q3 which are top 5 product with the highest average review rating?
select item_purchased, avg(review_rating) as "Average product Rating"
from customer_data
group by item_purchased
order by avg(review_rating)desc
limit 5;

-- Q4 compare the average purchase amount between standard and express shipping.
select shipping_type,
round(avg(purchase_amount),2)
from customer_data
where shipping_type in ('standard','Express')
group by shipping_type;

-- Q5 do subscribed customer spend more? compare average spend and total revenue between subscribers and non-subscribers
select subscription_status,
count(customer_id) as total_customer,
round(avg(purchase_amount),2) as avg_spend,
round(sum(purchase_amount),2) as total_revenue
from customer_data
group by subscription_status
order by total_revenue, avg_spend desc;

-- Q6 which 5 products have the highest percentage of purchases with discount applied?
select item_purchased,
round(sum(case when discount_applied='Yes' then 1 else 0 end)/count(*) *100,2) as discount_rate
from customer_data
group by item_purchased
order by discount_rate desc
limit 5;

-- Q7segment customer into new, returning and loyal based on their total number of previous purchases and show the count of each segment
WITH customer_type AS (
  SELECT customer_id, previous_purchases,
         CASE
           WHEN previous_purchases = 1 THEN 'New'
           WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
           ELSE 'Loyal'
         END AS customer_segment
  FROM customer_data
)
SELECT customer_segment, COUNT(*) AS no_of_customers
FROM customer_type
GROUP BY customer_segment;

-- Q8 what are the top 3 most purchased products within each category?
with item_counts as(
select category,
item_purchased,
count(customer_id) as total_orders,
row_number() over(partition by category order by count(customer_id)desc) as item_rank
from customer_data
group by category, item_purchased
)
select item_rank, category, item_purchased,total_orders
from item_counts
where item_rank <=3;

-- Q9 are customer who are repeat buysrs(more than 5 perevious purchases) also likely to subscribe?
select subscription_status,
count(customer_id) as repeat_buyers
from customer_data
where previous_purchases>5
group by subscription_status;

-- Q10 what is the revenue contributio of each age group?
select age_group,
sum(purchase_amount) as total_revenue
from customer_data
group by age_group
order by total_revenue desc;



